{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative Care for Lived Health</title>
  <meta name="description" content="A practical, personalized path to balanced living. Educational, evidence-aware guidance for common life conditions." />
  <link rel="stylesheet" href="assets/css/styles.css" />
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Conditions</a>
        <a href="/approach.html">Philosophy</a>
        <a href="/book.html" class="cta-link">Book</a>
        <a href="/contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero : Brief entry with condensed timeline planner -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-content">
          <h1 class="hero-title">Thoughtful, practical support for whole-life balance</h1>
          <p class="hero-lead">We help you turn scattered signals from sleep, stress, digestion, and rhythm into a clear, stepwise plan you can try this week. Educational and person-centered — not prescriptive cures.</p>

          <div class="hero-cta-row">
            <a id="primaryCta" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">About the team</a>
          </div>

          <div class="compact-roadmap">
            <strong>Three short phases</strong>
            <ol>
              <li>Stabilize: small, safe changes for daily flow</li>
              <li>Restore: build resilience and routines</li>
              <li>Integrate: maintain and adapt plans to life</li>
            </ol>
            <p class="disclaimer">Educational guidance only — not a medical diagnosis. Always consult providers for urgent concerns.</p>
          </div>
        </div>

        <aside class="hero-panel">
          <h3>Quick diagnostic</h3>
          <p>Choose how you feel right now to get a tailored suggested starting approach and an action you can try today.</p>

          <div class="mood-selector" role="radiogroup" aria-label="Mood to Method">
            <label class="mood">
              <input type="radio" name="mood" value="overwhelmed" />
              <span>Overwhelmed</span>
            </label>
            <label class="mood">
              <input type="radio" name="mood" value="drained" />
              <span>Drained</span>
            </label>
            <label class="mood">
              <input type="radio" name="mood" value="curious" />
              <span>Curious</span>
            </label>
            <label class="mood">
              <input type="radio" name="mood" value="restless" />
              <span>Restless</span>
            </label>
          </div>

          <div class="mood-result">
            <h4 id="moodMethodTitle">Recommended approach</h4>
            <p id="moodMethodText">Select a state above to see a suggested starting method and an updated action.</p>
          </div>
        </aside>
      </div>
    </section>

    <!-- Diagnostic details and short explanation -->
    <section class="diagnostic wrap">
      <h2>How we translate experience into a plan</h2>
      <p>We pair what you tell us about daily rhythm and symptoms with simple, testable steps. Each recommendation is framed as a hypothesis you can try — then adjust with guidance.</p>

      <div class="diagnostic-grid">
        <div class="card">
          <h3>Listen</h3>
          <p>We collect patterns across sleep, movement, mood, digestion, and stressors.</p>
        </div>
        <div class="card">
          <h3>Try</h3>
          <p>Short, measurable shifts to see what moves the needle in 1–3 weeks.</p>
        </div>
        <div class="card">
          <h3>Refine</h3>
          <p>Iterate on routines and supports so changes fit your life.</p>
        </div>
      </div>
    </section>

    <!-- Full timeline planner with phases and interactive checklist -->
    <section class="plan wrap" id="plan">
      <h2>Three-phase roadmap</h2>
      <p class="lead">Each phase is small, time-bound, and evidence-aware. Use this planner to set realistic steps for 6–12 weeks. Educational content only; if you have serious or worsening symptoms, reach out to licensed care.</p>

      <div class="timeline">
        <div class="phase" data-phase="1">
          <h3>Phase 1 — Stabilize (2–3 weeks)</h3>
          <p class="phase-desc">Focus on immediate, low-risk supports: sleep window, basic hydration, short movement, and clearing medication questions with your clinician.</p>
          <ul class="tasks">
            <li><label><input type="checkbox" class="task-checkbox" /> Set a consistent sleep window</label></li>
            <li><label><input type="checkbox" class="task-checkbox" /> Track 3 days of meals and mood</label></li>
            <li><label><input type="checkbox" class="task-checkbox" /> Try a 5–10 minute evening wind-down</label></li>
          </ul>
          <p class="disclaimer">Phase 1 is general educational guidance. It does not replace urgent medical care.</p>
        </div>

        <div class="phase" data-phase="2">
          <h3>Phase 2 — Restore (4–6 weeks)</h3>
          <p class="phase-desc">Build stability into routines and add restorative practices like breath work, graded activity, or focused sleep hygiene.</p>
          <ul class="tasks">
            <li><label><input type="checkbox" class="task-checkbox" /> Implement two restorative habits</label></li>
            <li><label><input type="checkbox" class="task-checkbox" /> Review symptom progress with a coach</label></li>
          </ul>
          <p class="disclaimer">If symptoms intensify, pause and consult a clinician. This plan is educational.</p>
        </div>

        <div class="phase" data-phase="3">
          <h3>Phase 3 — Integrate (ongoing)</h3>
          <p class="phase-desc">Adapt strategies to life stressors and transition to maintenance with periodic check-ins.</p>
          <ul class="tasks">
            <li><label><input type="checkbox" class="task-checkbox" /> Make one habit automatic</label></li>
            <li><label><input type="checkbox" class="task-checkbox" /> Plan maintenance check-ins (monthly)</label></li>
          </ul>
          <p class="disclaimer">This phase focuses on sustainable routines. Not a substitute for ongoing medical management when needed.</p>
        </div>
      </div>

      <div class="planner-actions">
        <button id="savePlan" class="btn">Save plan locally</button>
        <button id="resetPlan" class="btn ghost">Reset</button>
      </div>
    </section>

    <!-- Micro-habits section -->
    <section class="micro_habits wrap">
      <h2>Micro-habits to try this week</h2>
      <p>Small, concrete experiments you can do alone or with coaching support. Track for two weeks and note any changes.</p>

      <ul class="micro-list">
        <li><strong>Night anchor:</strong> 10 minutes before bed, dim lights and list three wins from today.</li>
        <li><strong>Midday reset:</strong> Two brief movement breaks (3–5 minutes) after lunch and mid-afternoon.</li>
        <li><strong>Signal snack:</strong> A protein-led snack within an hour of activity to support energy.</li>
      </ul>
    </section>

    <!-- Pricing / programs -->
    <section class="pricing wrap">
      <h2>Programs and investment</h2>
      <p class="lead">We offer single consultations, short tracks, and ongoing mentoring. Pricing is framed as educational support packages rather than cure promises.</p>

      <div class="pricing-grid">
        <div class="price">
          <h3>Starter Session</h3>
          <p class="cost">$120</p>
          <p>One 50-minute consultation to map priorities and a 2-week micro-plan.</p>
          <a class="btn" href="/book.html">Book a starter</a>
        </div>
        <div class="price featured">
          <h3>Foundations Track</h3>
          <p class="cost">$420 / 8 weeks</p>
          <p>Focused, stepwise support with two check-ins and a coach-driven refinement.</p>
          <a class="btn primary" href="/book.html">Start Foundations</a>
        </div>
        <div class="price">
          <h3>Maintenance Plan</h3>
          <p class="cost">$85 / month</p>
          <p>Monthly check-ins and ongoing habit nudges to keep momentum.</p>
          <a class="btn" href="/pricing.html">Learn more</a>
        </div>
      </div>

      <p class="pricing-note">All programs emphasize education and lifestyle experimentation. Not billed as medical cures.</p>
    </section>

    <!-- Call to action -->
    <section class="cta wrap">
      <div class="cta-box">
        <h2>Ready to test one small change?</h2>
        <p>Start with a single, manageable step and see what shifts in two weeks. We use real-world tracking and adjust from there.</p>
        <a id="secondaryCta" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="contact-sm">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <nav class="footer-nav">
          <a href="/services.html">Offerings</a>
          <a href="/approach.html">Approach</a>
          <a href="/about.html">Team</a>
          <a href="/contact.html">Contact</a>
        </nav>
      </div>
      <div>
        <p class="small">© <span id="year">2026</span> {{BUSINESS_NAME}} — Educational services only.</p>
      </div>
    </div>
  </footer>
</body>
</html>"} 
